// STEP 1/3 — VALIDATE GATE
// out1 (valido) -> engine ; out2 (invalido) -> http response 4xx
var INTENTS = ['DISABLE','ENABLE','FORCE_DISABLE','FORCE_ENABLE','QUERY'];
var SYSTEMS = ['GCDR','ALARMS','THINGSBOARD','MOBILE_APP','PRE_SETUP','MANUAL'];
function reject(m, code, message){ m.statusCode = 400; m.headers = { 'Content-Type':'application/json' }; m.payload = { ok:false, error:code, message:message }; return [null, m]; }
function uuid(){ return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c){ var r=(Math.random()*16)|0; return (c==='x'?r:(r&0x3)|0x8).toString(16); }); }
var body = msg.payload;
var nowMs = Date.now();
if (!body || typeof body !== 'object') return reject(msg,'INVALID_PAYLOAD','corpo ausente ou nao e JSON');
if (!body.intent && (body.mqttSyncStatus==='enable' || body.mqttSyncStatus==='disable')) {
  body = { schemaVersion:'legacy', intent: body.mqttSyncStatus==='enable'?'FORCE_ENABLE':'FORCE_DISABLE', hold:{ reasonCode:'MANUAL_OPS', reason:'compat v1' }, actor:{ system:'MANUAL' }, request:{} };
}
var intent = String(body.intent||'').toUpperCase();
if (INTENTS.indexOf(intent)===-1) return reject(msg,'INVALID_INTENT','intent deve ser um de: '+INTENTS.join(', '));
var actor = body.actor || {};
if (actor.system && SYSTEMS.indexOf(actor.system)===-1) return reject(msg,'INVALID_SYSTEM','actor.system invalido: '+actor.system);
var hold = body.hold || {};
if ((intent==='DISABLE'||intent==='ENABLE') && !hold.holdId) return reject(msg,'MISSING_HOLD_ID', intent+' requer hold.holdId');
if (hold.ttlSeconds!=null && (typeof hold.ttlSeconds!=='number' || hold.ttlSeconds<0)) return reject(msg,'INVALID_TTL','hold.ttlSeconds deve ser numero >= 0');
var rq = body.request || {};
var envelope = {
  schemaVersion: body.schemaVersion || '2.0',
  intent: intent,
  hold: { holdId: hold.holdId||null, ttlSeconds: hold.ttlSeconds!=null?hold.ttlSeconds:null, reasonCode: hold.reasonCode||'OTHER', reason: hold.reason||null },
  scope: body.scope || { level:'CENTRAL', targets:[] },
  actor: { system: actor.system||'UNKNOWN', instanceId: actor.instanceId||null, version: actor.version||null, user: actor.user||null, requestIp: actor.requestIp || (msg.req && msg.req.ip) || null },
  request: { requestId: rq.requestId||uuid(), correlationId: rq.correlationId||null, idempotencyKey: rq.idempotencyKey||rq.requestId||null, requestedAt: rq.requestedAt || new Date(rq.requestedAtMs||nowMs).toISOString(), requestedAtMs: rq.requestedAtMs||nowMs, receivedAtMs: nowMs }
};
msg.envelope = envelope;
msg.params = [envelope];
return [msg, null];

// STEP 2/3 — ENGINE (holds + TTL + record append-only + global derivado)
// consome msg.envelope (step 1); fallback standalone normaliza msg.payload
// out1 -> http response (RESPONSE) ; out2 -> persistencia/forward (RECORD)
var AUDIT_RING_MAX=200, SEEN_TTL_MS=6*60*60*1000, DEFAULT_TTL_SECONDS=900, MAX_TTL_SECONDS=6*60*60;
var CENTRAL = { id:'ilha-plaza-al1', name:'Ilha Plaza AL1', gatewayId:'81a60176-222c-4bb9-88f5-bc2b47802d82' };
var VALID_INTENTS=['DISABLE','ENABLE','FORCE_DISABLE','FORCE_ENABLE','QUERY'];
var VALID_SYSTEMS=['GCDR','ALARMS','THINGSBOARD','MOBILE_APP','PRE_SETUP','MANUAL','LEGACY','UNKNOWN'];
function uuid(){ return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,function(c){ var r=(Math.random()*16)|0; var v=c==='x'?r:(r&0x3)|0x8; return v.toString(16); }); }
function iso(ms){ return new Date(ms).toISOString(); }
function clampTtl(s){ var n=Number(s); if(!isFinite(n)||n<0) return DEFAULT_TTL_SECONDS; if(n===0) return 0; return Math.min(n,MAX_TTL_SECONDS); }
function fail(code,message,h){ return { _error:true, errorCode:code, message:message, httpStatus:h||400 }; }
function normalizeRequest(b,nowMs){ if(b && typeof b==='object' && b.intent) return b; var legacy = b && typeof b==='object' ? b.mqttSyncStatus : b; if(legacy==='enable'||legacy==='disable'){ return { schemaVersion:'legacy', intent: legacy==='enable'?'FORCE_ENABLE':'FORCE_DISABLE', hold:{reasonCode:'MANUAL_OPS',reason:'Compat v1'}, actor:{system:'LEGACY'}, request:{requestId:uuid(),requestedAtMs:nowMs,requestedAt:iso(nowMs)} }; } return null; }
function sweepExpired(holds,nowMs){ var removed=[]; Object.keys(holds).forEach(function(id){ var h=holds[id]; if(h.expiresAtMs && h.expiresAtMs<=nowMs){ removed.push(h); delete holds[id]; } }); return removed; }
function activeHoldsView(holds){ return Object.keys(holds).map(function(id){ var h=holds[id]; return { holdId:h.holdId, system:h.system, reasonCode:h.reasonCode, acquiredAt:h.acquiredAt, expiresAt: h.expiresAtMs?iso(h.expiresAtMs):null }; }); }
var nowMs=Date.now();
var holds = global.get('mqttHolds') || {};
var seen = global.get('mqttSeenReqs') || {};
var req = msg.envelope || normalizeRequest(msg.payload, nowMs);
if(!req){ msg.statusCode=400; msg.payload={ ok:false, errorCode:'INVALID_PAYLOAD', message:'Esperado v2 { intent } ou v1 { mqttSyncStatus }' }; return [msg, null]; }
var intent=String(req.intent||'').toUpperCase();
var actor=req.actor||{}; var rq=req.request||{}; var hold=req.hold||{};
var requestId=rq.requestId||uuid(); var idemKey=rq.idempotencyKey||requestId; var requestedAtMs=Number(rq.requestedAtMs)||nowMs;
var prevStatus = (global.get('mqttSyncStatus')==='disable')?'disable':'enable';
var err=null;
if(VALID_INTENTS.indexOf(intent)===-1) err=fail('INVALID_INTENT','intent invalido: '+intent);
else if(actor.system && VALID_SYSTEMS.indexOf(actor.system)===-1) err=fail('INVALID_SYSTEM','actor.system invalido: '+actor.system);
else if((intent==='DISABLE'||intent==='ENABLE') && !hold.holdId) err=fail('MISSING_HOLD_ID', intent+' requer hold.holdId');
if(err){ msg.statusCode=err.httpStatus; msg.payload={ ok:false, errorCode:err.errorCode, message:err.message, requestId:requestId }; return [msg, null]; }
Object.keys(seen).forEach(function(k){ if(nowMs-seen[k] > SEEN_TTL_MS) delete seen[k]; });
var expired = sweepExpired(holds, nowMs);
var decidedBy='HOLD_COUNT'; var changedByThisReq=true;
if(intent!=='QUERY' && seen[idemKey]){ decidedBy='NOOP'; changedByThisReq=false; }
else {
  switch(intent){
    case 'QUERY': decidedBy='NOOP'; changedByThisReq=false; break;
    case 'DISABLE': { var ttl=clampTtl(hold.ttlSeconds!=null?hold.ttlSeconds:DEFAULT_TTL_SECONDS); var existed=!!holds[hold.holdId]; holds[hold.holdId]={ holdId:hold.holdId, system:actor.system||'UNKNOWN', reasonCode:hold.reasonCode||'OTHER', reason:hold.reason||null, acquiredAt: existed?holds[hold.holdId].acquiredAt:iso(nowMs), acquiredAtMs: existed?holds[hold.holdId].acquiredAtMs:nowMs, expiresAtMs: ttl===0?null:nowMs+ttl*1000 }; seen[idemKey]=nowMs; changedByThisReq=!existed; break; }
    case 'ENABLE': { if(holds[hold.holdId]){ delete holds[hold.holdId]; seen[idemKey]=nowMs; } else { decidedBy='NOOP'; changedByThisReq=false; } break; }
    case 'FORCE_DISABLE': { holds['manual:force:'+requestId]={ holdId:'manual:force:'+requestId, system:actor.system||'MANUAL', reasonCode:hold.reasonCode||'MANUAL_OPS', reason:hold.reason||'FORCE_DISABLE', acquiredAt:iso(nowMs), acquiredAtMs:nowMs, expiresAtMs: hold.ttlSeconds!=null?nowMs+clampTtl(hold.ttlSeconds)*1000:null }; seen[idemKey]=nowMs; decidedBy='FORCE'; break; }
    case 'FORCE_ENABLE': { holds={}; seen[idemKey]=nowMs; decidedBy='FORCE'; break; }
  }
}
var holdCount=Object.keys(holds).length;
var effectiveStatus = holdCount>0?'disable':'enable';
if(expired.length && decidedBy==='HOLD_COUNT' && !changedByThisReq) decidedBy='TTL_EXPIRED';
var changed = effectiveStatus!==prevStatus;
global.set('mqttHolds', holds);
global.set('mqttSeenReqs', seen);
global.set('mqttSyncStatus', effectiveStatus);
if(intent!=='QUERY') global.set('mqttLastChange', { at:iso(nowMs), by:actor.system||'UNKNOWN', intent:intent, requestId:requestId });
var record = { schemaVersion: req.schemaVersion||'2.0', intent:intent, hold: req.hold||null, scope: req.scope||{level:'CENTRAL',targets:[]}, actor:actor, request:{ requestId:requestId, correlationId:rq.correlationId||null, idempotencyKey:rq.idempotencyKey||null, requestedAt: rq.requestedAt||iso(requestedAtMs), requestedAtMs:requestedAtMs }, outcome:{ effectiveStatus:effectiveStatus, previousStatus:prevStatus, changed:changed, decidedBy:decidedBy, activeHolds:activeHoldsView(holds), holdCount:holdCount, expiredHolds: expired.map(function(h){return h.holdId;}), receivedAt:iso(nowMs), receivedAtMs:nowMs, clockSkewMs: nowMs-requestedAtMs, node:{ central:CENTRAL, nodeRedVersion: (global.get('nodeRedVersion')||null) } }, logKey: 'mqttSync:'+CENTRAL.id+':'+requestId };
var ring = global.get('mqttAuditLog') || [];
if(intent!=='QUERY'){ ring.push(record); if(ring.length>AUDIT_RING_MAX) ring=ring.slice(ring.length-AUDIT_RING_MAX); global.set('mqttAuditLog', ring); }
node.status({ fill: effectiveStatus==='enable'?'green':'yellow', shape:'dot', text: effectiveStatus+' · holds '+holdCount });
msg.statusCode=200;
msg.payload = { ok:true, effectiveStatus:effectiveStatus, changed:changed, decidedBy:decidedBy, holdCount:holdCount, expiresAt: (function(){ var next=null; Object.keys(holds).forEach(function(id){ var e=holds[id].expiresAtMs; if(e && (next===null||e<next)) next=e; }); return next?iso(next):null; })(), requestId:requestId, correlationId: rq.correlationId||null };
var recordMsg = (intent==='QUERY') ? null : { payload: record, logKey: record.logKey };
return [msg, recordMsg];

// STEP 3/3 — GET STATUS (TTL sweep on read)
var CENTRAL = { id:'ilha-plaza-al1', name:'Ilha Plaza AL1', gatewayId:'81a60176-222c-4bb9-88f5-bc2b47802d82' };
function iso(ms){ return new Date(ms).toISOString(); }
var nowMs=Date.now();
var holds = global.get('mqttHolds') || {};
var expired=[];
Object.keys(holds).forEach(function(id){ var h=holds[id]; if(h.expiresAtMs && h.expiresAtMs<=nowMs){ expired.push(id); delete holds[id]; } });
var holdCount=Object.keys(holds).length;
var effectiveStatus = holdCount>0?'disable':'enable';
if(expired.length){ global.set('mqttHolds', holds); node.warn('[mqttSyncStatus] TTL sweep removeu '+expired.length+' hold(s) -> '+effectiveStatus); }
global.set('mqttSyncStatus', effectiveStatus);
node.status({ fill: effectiveStatus==='enable'?'green':'yellow', shape:'dot', text: effectiveStatus+' · holds '+holdCount });
var activeHolds = Object.keys(holds).map(function(id){ var h=holds[id]; return { holdId:h.holdId, system:h.system, reasonCode:h.reasonCode, reason:h.reason||null, acquiredAt:h.acquiredAt, expiresAt: h.expiresAtMs?iso(h.expiresAtMs):null }; });
msg.statusCode=200;
msg.payload = { mqttSyncStatus: effectiveStatus, effectiveStatus: effectiveStatus, holdCount: holdCount, activeHolds: activeHolds, expiredNow: expired, lastChange: global.get('mqttLastChange')||null, central: { id:CENTRAL.id, gatewayId:CENTRAL.gatewayId }, serverTime: iso(nowMs) };
return msg;
